	var sideId any = this.SafeString(delta, "orderType")
	var side any = ccxt.Ternary(ccxt.IsTrue((ccxt.IsEqual(sideId, "bid"))), "bids", "asks")
	var bidAsk any = this.ParseOrderBookBidAsk(delta, "price", "quantity")
