func (this *BithumbCore) HandleBalance(client any, message any) {
	//
	//    {
	//        "type": "myAsset",
	//        "assets": [
	//            {
	//                "currency": "KRW",
	//                "balance": "2061832.35",
	//                "locked": "3824127.3"
	//            }
	//        ],
	//        "asset_timestamp": 1727052537592,
	//        "timestamp": 1727052537687,
	//        "stream_type": "REALTIME"
	//    }
	//
	var messageHash string = "myAsset"
	var assets any = this.SafeList(message, "assets", []any{})
	if ccxt.IsTrue(ccxt.IsEqual(this.Balance, nil)) {
		this.Balance = map[string]any{}
	}
	for i := 0; ccxt.IsLessThan(i, ccxt.GetArrayLength(assets)); i++ {
		var asset any = ccxt.GetValue(assets, i)
		var currencyId any = this.SafeString(asset, "currency")
		var code any = this.SafeCurrencyCode(currencyId)
		var account any = this.Account()
		ccxt.AddElementToObject(account, "free", this.SafeString(asset, "balance"))
		ccxt.AddElementToObject(account, "used", this.SafeString(asset, "locked"))
		if ccxt.IsTrue(!ccxt.IsEqual(code, nil)) {
			ccxt.AddElementToObject(this.Balance, code, account)
		}
	}
	ccxt.AddElementToObject(this.Balance, "info", message)
	var timestamp any = this.SafeInteger(message, "timestamp")
	ccxt.AddElementToObject(this.Balance, "timestamp", timestamp)
	ccxt.AddElementToObject(this.Balance, "datetime", this.Iso8601(timestamp))
	this.Balance = this.SafeBalance(this.Balance)
	client.(ccxt.ClientInterface).Resolve(this.Balance, messageHash)
}

/**
 * @ignore
 * @method
 * @name bithumb#buildGen2SubscriptionRequest
 * @description builds the SUBSCRIBE frame for the generation 2 private socket - the venue replaces
 * the socket's whole subscription list with every SUBSCRIBE frame, so the frame always carries the
 * union of everything subscribed so far, otherwise a second stream (e.g. watchOrders after
 * watchBalance) would silently cancel the first one
 * @param {string} subscriptionType the venue subscription type ('myAsset' / 'myOrder')
 * @param {object} subscription the subscription entry for that type
 * @returns {object[]} the SUBSCRIBE frame to send
 */
func (this *BithumbCore) BuildGen2SubscriptionRequest(subscriptionType any, subscription any) any {
	var wsOptions any = this.SafeDict(this.Options, "ws", map[string]any{})
	var subscriptions any = this.SafeDict(wsOptions, "gen2Subscriptions", map[string]any{})
	ccxt.AddElementToObject(subscriptions, subscriptionType, subscription)
	ccxt.AddElementToObject(wsOptions, "gen2Subscriptions", subscriptions)
	ccxt.AddElementToObject(this.Options, "ws", wsOptions)
	var request any = []any{map[string]any{
		"ticket": "ccxt",
	}}
	var keys []string = ccxt.ObjectKeys(subscriptions)
	for i := 0; ccxt.IsLessThan(i, ccxt.GetArrayLength(keys)); i++ {
		ccxt.AppendToArray(&request, ccxt.GetValue(subscriptions, ccxt.GetValue(keys, i)))
	}
	return request
}
func (this *BithumbCore) Authenticate(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.authenticateBody(ch, optionalArgs...)
	return ch
}
func (this *BithumbCore) authenticateBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	params := ccxt.GetArg(optionalArgs, 0, map[string]any{})
	_ = params
	this.CheckRequiredCredentials()
	var wsOptions any = this.SafeDict(this.Options, "ws", map[string]any{})
	var authenticated any = this.SafeString(wsOptions, "token")
	if ccxt.IsTrue(ccxt.IsEqual(authenticated, nil)) {
		var payload map[string]any = map[string]any{
			"access_key": this.ApiKey,
			"nonce":      this.Uuid(),
			"timestamp":  this.Milliseconds(),
		}
		var jwtToken string = ccxt.Jwt(payload, this.Encode(this.Secret), ccxt.Sha256)
		ccxt.AddElementToObject(wsOptions, "token", jwtToken)
		ccxt.AddElementToObject(wsOptions, "options", map[string]any{
			"headers": map[string]any{
				"authorization": ccxt.Add("Bearer ", jwtToken),
			},
		})
		ccxt.AddElementToObject(this.Options, "ws", wsOptions)
	}
	var url any = ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"), "privateGen2")
	var client any = this.Client(url)

	ch <- client
	return nil
}

/**
 * @method
 * @name bithumb#watchOrders
 * @description watches information on multiple orders made by the user
 * @see https://apidocs.bithumb.com/v2.1.5/reference/%EB%82%B4-%EC%A3%BC%EB%AC%B8-%EB%B0%8F-%EC%B2%B4%EA%B2%B0-myorder
 * @param {string} symbol unified market symbol of the market orders were made in
 * @param {int} [since] the earliest time in ms to fetch orders for
 * @param {int} [limit] the maximum number of order structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string[]} [params.codes] market codes to filter orders
 * @param {int} [params.generation] *only generation 2 is supported* if you want to use the API generation 1 or 2, default is 2
 * @returns {object[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *BithumbCore) WatchOrders(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchOrdersBody(ch, optionalArgs...)
	return ch
}
func (this *BithumbCore) watchOrdersBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	symbol := ccxt.GetArg(optionalArgs, 0, nil)
	_ = symbol
	since := ccxt.GetArg(optionalArgs, 1, nil)
	_ = since
	limit := ccxt.GetArg(optionalArgs, 2, nil)
	_ = limit
	params := ccxt.GetArg(optionalArgs, 3, map[string]any{})
	_ = params
	if ccxt.IsTrue(ccxt.IsEqual(this.Markets, nil)) {

		retRes90212 := (<-this.LoadMarkets())
		ccxt.PanicOnError(retRes90212)
	}
	var generation any = nil
	generationparamsVariable := this.HandleOptionAndParams(params, "watchOrders", "generation", 2)
	generation = ccxt.GetValue(generationparamsVariable, 0)
	params = ccxt.GetValue(generationparamsVariable, 1)
	if ccxt.IsTrue(!ccxt.IsEqual(generation, 2)) {
		panic(ccxt.BadRequest(ccxt.Add(this.Id, " watchOrders() is only supported for the generation 2 API")))
	}

	retRes9098 := (<-this.Authenticate())
	ccxt.PanicOnError(retRes9098)
	var url any = ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"), "privateGen2")
	var messageHash any = "myOrder"
	var codes any = this.SafeList(params, "codes", []any{})
	var request any = this.BuildGen2SubscriptionRequest(messageHash, map[string]any{
		"type":  messageHash,
		"codes": codes,
	})
	if ccxt.IsTrue(!ccxt.IsEqual(symbol, nil)) {
		var market any = this.Market(symbol)
		symbol = ccxt.GetValue(market, "symbol")
		messageHash = ccxt.Add(ccxt.Add(messageHash, ":"), symbol)
	}

	orders := (<-this.Watch(url, messageHash, request, messageHash))
	ccxt.PanicOnError(orders)
	if ccxt.IsTrue(this.NewUpdates) {
		limit = ccxt.ToGetsLimit(orders).GetLimit(symbol, limit)
	}

	ch <- this.FilterBySymbolSinceLimit(orders, symbol, since, limit, true)
	return nil
}
func (this *BithumbCore) HandleOrders(client any, message any) {
	//
	//    {
	//        "type": "myOrder",
	//        "code": "KRW-BTC",
	//        "uuid": "C0101000000001818113",
	//        "ask_bid": "BID",
	//        "order_type": "limit",
	//        "state": "trade",
	//        "trade_uuid": "C0101000000001744207",
	//        "price": 1927000,
	//        "volume": 0.4697,
	//        "remaining_volume": 0.0803,
	//        "executed_volume": 0.4697,
	//        "trades_count": 1,
	//        "reserved_fee": 0,
	//        "remaining_fee": 0,
	//        "paid_fee": 0,
	//        "executed_funds": 905111.9000,
	//        "trade_timestamp": 1727052318148,
	//        "order_timestamp": 1727052318074,
	//        "timestamp": 1727052318369,
	//        "stream_type": "REALTIME"
	//    }
	//
	var messageHash string = "myOrder"
	var parsed any = this.ParseWsOrder(message)
	var symbol any = this.SafeString(parsed, "symbol")
	// const orderId = this.safeString (parsed, 'id')
	if ccxt.IsTrue(ccxt.IsEqual(this.Orders, nil)) {
		var limit any = this.SafeInteger(this.Options, "ordersLimit", 1000)
		this.Orders = ccxt.NewArrayCacheBySymbolById(limit)
	}
	var cachedOrders any = this.Orders
	cachedOrders.(ccxt.Appender).Append(parsed)
	client.(ccxt.ClientInterface).Resolve(cachedOrders, messageHash)
	var symbolSpecificMessageHash any = ccxt.Add(ccxt.Add(messageHash, ":"), symbol)
	client.(ccxt.ClientInterface).Resolve(cachedOrders, symbolSpecificMessageHash)
}
func (this *BithumbCore) ParseWsOrder(order any, optionalArgs ...any) any {
	//
	//    {
	//        "type": "myOrder",
	//        "code": "KRW-BTC",
	//        "uuid": "C0101000000001818113",
	//        "ask_bid": "BID",
	//        "order_type": "limit",
	//        "state": "trade",
	//        "trade_uuid": "C0101000000001744207",
	//        "price": 1927000,
	//        "volume": 0.4697,
	//        "remaining_volume": 0.0803,
	//        "executed_volume": 0.4697,
	//        "trades_count": 1,
	//        "reserved_fee": 0,
	//        "remaining_fee": 0,
	//        "paid_fee": 0,
	//        "executed_funds": 905111.9000,
	//        "trade_timestamp": 1727052318148,
	//        "order_timestamp": 1727052318074,
	//        "timestamp": 1727052318369,
	//        "stream_type": "REALTIME"
	//    }
	//
	market := ccxt.GetArg(optionalArgs, 0, nil)
	_ = market
	var marketId any = this.SafeString(order, "code")
	var symbol any = this.SafeSymbol(marketId, market, "-")
	var timestamp any = this.SafeInteger(order, "order_timestamp")
	var sideId any = this.SafeString(order, "ask_bid")
	var side any = this.SafeStringLower(order, "side")
	if ccxt.IsTrue(!ccxt.IsEqual(sideId, nil)) {
		side = ccxt.Ternary(ccxt.IsTrue((ccxt.IsEqual(sideId, "BID"))), ("buy"), ("sell"))
	}
	var typeId any = this.SafeString(order, "order_type")
	var typeVar any = nil
	if ccxt.IsTrue(ccxt.IsEqual(typeId, "limit")) {
		typeVar = "limit"
	} else if ccxt.IsTrue(ccxt.IsEqual(typeId, "price")) {
		typeVar = "market"
	} else if ccxt.IsTrue(ccxt.IsEqual(typeId, "market")) {
		typeVar = "market"
	}
	var stateId any = this.SafeString(order, "state")
	var status any = nil
	if ccxt.IsTrue(ccxt.IsEqual(stateId, "wait")) {
		status = "open"
	} else if ccxt.IsTrue(ccxt.IsEqual(stateId, "trade")) {
		status = "open"
	} else if ccxt.IsTrue(ccxt.IsEqual(stateId, "done")) {
		status = "closed"
	} else if ccxt.IsTrue(ccxt.IsEqual(stateId, "cancel")) {
		status = "canceled"
	}
	var price any = this.SafeString2(order, "price", "order_price")
	var amount any = this.SafeString2(order, "volume", "order_quantity")
	var remaining any = this.SafeString(order, "remaining_volume")
	var filled any = this.SafeString(order, "executed_volume")
	var cost any = this.SafeString(order, "executed_funds")
	var feeCost any = this.SafeString(order, "paid_fee")
	var fee any = nil
	if ccxt.IsTrue(!ccxt.IsEqual(feeCost, nil)) {
		var marketForFee any = this.SafeMarket(marketId, market)
		var feeCurrency any = this.SafeString(marketForFee, "quote")
		fee = map[string]any{
			"cost":     feeCost,
			"currency": feeCurrency,
		}
	}
	return this.SafeOrder(map[string]any{
		"info":               order,
		"id":                 this.SafeString2(order, "uuid", "order_id"),
		"clientOrderId":      nil,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": this.SafeInteger(order, "trade_timestamp"),
		"symbol":             symbol,
		"type":               typeVar,
		"timeInForce":        nil,
		"postOnly":           nil,
		"side":               side,
		"price":              price,
		"stopPrice":          nil,
		"triggerPrice":       nil,
		"amount":             amount,
		"cost":               cost,
		"average":            nil,
		"filled":             filled,
		"remaining":          remaining,
		"status":             status,
		"fee":                fee,
		"trades":             nil,
	}, market)
}
func (this *BithumbCore) HandleMessage(client any, message any) {
	if ccxt.IsTrue(ccxt.IsString(message)) {
		var content string = ccxt.ToLower(message)
		if ccxt.IsTrue(ccxt.IsEqual(content, "pong")) {
			this.HandlePong(client, message)
			return
		}
		if ccxt.IsTrue(ccxt.IsEqual(content, "ping")) {
			this.HandlePing(client, message)
			return
		}
		return
	}
	var status any = this.SafeString(message, "status")
	if ccxt.IsTrue(ccxt.IsEqual(status, "UP")) {
		this.HandlePong(client, message)
		return
	}
	if ccxt.IsTrue(ccxt.IsTrue((ccxt.InOp(message, "pong"))) || ccxt.IsTrue((ccxt.InOp(message, "PINGPONG")))) {
		this.HandlePong(client, message)
		return
	}
	if ccxt.IsTrue(ccxt.InOp(message, "ping")) {
		this.HandlePing(client, message)
		return
	}
	if ccxt.IsTrue(!ccxt.IsEqual(this.HandleErrorMessage(client, message), true)) {
		return
	}
	var topic any = this.SafeString(message, "type")
	if ccxt.IsTrue(!ccxt.IsEqual(topic, nil)) {
		var methods map[string]any = map[string]any{
			"ticker":         this.HandleTicker,
			"orderbookdepth": this.HandleOrderBook,
			"orderbook":      this.HandleOrderBook,
			"transaction":    this.HandleTrades,
			"trade":          this.HandleTrades,
			"myAsset":        this.HandleBalance,
			"myOrder":        this.HandleOrders,
		}
		var method any = this.SafeValue(methods, topic)
		if ccxt.IsTrue(!ccxt.IsEqual(method, nil)) {
			ccxt.CallDynamically(method, client, message)
		}
	}
}

func (this *BithumbCore) Init(userConfig map[string]any) {
	this.base.Init(this.DeepExtend(this.Describe(), userConfig))
	this.Itf = this
	this.Exchange.DerivedExchange = this
}
